spawn(function()
	wait()
	local children4 = workspace.Boats:GetChildren()

	for k17, v17 in pairs(children4) do
		local descendants4 = v17:GetDescendants()

		for k18, v18 in pairs(descendants4) do
			v18.CanCollide = true
		end
	end

	wait()
	local children5 = workspace.Boats:GetChildren()

	for k19, v19 in pairs(children5) do
		local descendants5 = v19:GetDescendants()

		for k20, v20 in pairs(descendants5) do
			v20.CanCollide = true
		end
	end

	wait()
	-- [envlog] the statements above repeat forever (loop)
end)

